        m=re.search(r"Line (\d+) \((\d+)\)\. Indent: actual = (-?\d+), visual = (-?\d+): (.*)",line)
        if m: out.append((int(m.group(3)),int(m.group(4)),m.group(5)))
    return out
def show(setup,target):
    print("setup",repr(setup),"target",repr(target), traces(setup+target+"\nPROBE\n"))
for setup in ["\\begin{itemize}\n", "\\begin{a}\\begin{b}\n", "{\n"]:
    for t in [r"\begin{c}", r"\begin{c} }", r"\begin{c} {", r"\end{c}", r"\end{c} {", r"\end{c} }", r"\foo{c} }", r"x }", r"x {", "{ }", "} {"]:
        show(setup,t)
