import subprocess
def fmt(inp, extra=[]):
    r=subprocess.run(["/workspace/executable","--stdin","--noconfig"]+extra, input=inp, capture_output=True, text=True)
    return r.stdout
for extra in [[],["-t","4"],["-t","1"],["--usetabs"],["-t","0"]]:
    print("extra",extra,repr(fmt("a\tb\nc \t d\te \t f\n",extra)))
