use std::sync::Mutex;

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub enum Level {
    Error = 1,
    Warn = 2,
    Info = 3,
    Trace = 4,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Verbosity {
    Error,
    Warn,
    Info,
    Trace,
}

impl Verbosity {
    pub fn from_name(s: &str) -> Self {
        match s {
            "error" => Self::Error,
            "warn" => Self::Warn,
            "info" => Self::Info,
            "trace" => Self::Trace,
            _ => Self::Warn,
        }
    }
    pub fn name(self) -> &'static str {
        match self {
            Self::Error => "error",
            Self::Warn => "warn",
            Self::Info => "info",
            Self::Trace => "trace",
        }
    }
    fn allows(self, level: Level) -> bool {
        let limit = match self {
            Self::Error => Level::Error,
            Self::Warn => Level::Warn,
            Self::Info => Level::Info,
            Self::Trace => Level::Trace,
        };
        level <= limit
    }
}

pub struct Logger {
    verbosity: Verbosity,
    buffer: Mutex<Vec<String>>,
}

impl Logger {
    pub fn new(verbosity: Verbosity) -> Self {
        Self { verbosity, buffer: Mutex::new(Vec::new()) }
    }
    pub fn log(&self, level: Level, file: &str, message: &str) {
        if self.verbosity.allows(level) {
            let name = match level {
                Level::Error => "ERROR",
                Level::Warn => "WARN",
                Level::Info => "INFO",
                Level::Trace => "TRACE",
            };
            self.buffer.lock().unwrap().push(format!("{}: tex-fmt {}: {}\n", name, file, message));
        }
    }
    pub fn error(&self, file: &str, message: &str) { self.log(Level::Error, file, message); }
    pub fn warn(&self, file: &str, message: &str) { self.log(Level::Warn, file, message); }
    pub fn info(&self, file: &str, message: &str) { self.log(Level::Info, file, message); }
    pub fn trace(&self, file: &str, message: &str) { self.log(Level::Trace, file, message); }
    pub fn flush(&self) {
        let mut buf = self.buffer.lock().unwrap();
        for line in buf.drain(..) {
            eprint!("{}", line);
        }
    }
}
