{"command":"cat > src/format.rs <<'RS'
use crate::config::{ResolvedArgs, TabChar};
use crate::logging::{Level, Logger};

#[derive(Clone, Copy, Debug, Default)]
pub struct Indent {
    pub actual: i8,
    pub visual: i8,
}

#[derive(Clone, Debug)]
struct Line {
    text: String,
    old: usize,
}

const SPLIT_COMMANDS: [&str; 5] = ["part", "chapter", "section", "subsection", "subsubsection"];

fn comment_start(text: &str) -> Option<usize> {
    let bytes = text.as_bytes();
    for i in 0..bytes.len() {
        if bytes[i] == b'%' && (i == 0 || bytes[i - 1] != b'\\') {
            return Some(i);
        }
    }
    None
}

fn code_portion(text: &str) -> &str {
    match comment_start(text) {
        Some(i) => &text[..i],
        None => text,
    }
}

fn suppress_command_patterns(code: &str) -> bool {
    code.contains("\\verb|") || code.contains("\\verb+") || code.contains("\\mintinline")
}

fn find_item_pattern(code: &str) -> Option<usize> {
    if suppress_command_patterns(code) {
        return None;
    }
    let mut start = 0usize;
    while let Some(pos) = code[start..].find("\\item") {
        let idx = start + pos;
        let after = code[idx + 5..].chars().next();
        let valid = match after {
            None => true,
            Some(c) => !c.is_ascii_alphabetic(),
        };
        if valid {
            return Some(idx);
        }
        start = idx + 5;
    }
    None
}

fn split_pattern_at(code: &str, idx: usize) -> Option<usize> {
    let rest = &code[idx..];
    if rest.starts_with("\\begin{") || rest.starts_with("\\end{") {
        return Some("\\begin{".len().min(rest.len()));
    }
    if find_item_pattern(&code[idx..]) == Some(0) {
        return Some(5);
    }
    for cmd in SPLIT_COMMANDS {
        let prefix = format!("\\{}", cmd);
        if rest.starts_with(&prefix) {
            let after = &rest[prefix.len()..];
            if after.starts_with('{') || after.starts_with("*{") {
                return Some(prefix.len());
            }
        }
    }
    None
}

fn find_split_point(text: &str) -> Option<usize> {
    let code = code_portion(text);
    if suppress_command_patterns(code) {
        return None;
    }
    // Search byte positions from 1 onwards for the earliest pattern start.
    for idx in 1..code.len() {
        if !code.is_char_boundary(idx) {
            continue;
        }
        if split_pattern_at(code, idx).is_some() {
            return Some(idx);
        }
    }
    None
}

fn env_delta(name: &str, args: &ResolvedArgs) -> i8 {
    if args.no_indent_envs.iter().any(|x| x == name) {
        0
    } else if args.lists.iter().any(|x| x == name) {
        2
    } else {
        1
    }
}

#[derive(Clone, Copy)]
struct EnvEvent {
    delta: i8,
    closed: bool,
    is_begin: bool,
}

fn env_events(code: &str, args: &ResolvedArgs) -> Vec<EnvEvent> {
    if suppress_command_patterns(code) {
        return Vec::new();
    }
    let mut events = Vec::new();
    let bytes = code.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        let is_begin = code[i..].starts_with("\\begin{");
        let is_end = code[i..].starts_with("\\end{");
        if is_begin || is_end {
            let prefix_len = if is_begin { 7 } else { 5 };
            let name_start = i + prefix_len;
            if let Some(close_rel) = code[name_start..].find('}') {
                let name = &code[name_start..name_start + close_rel];
                let d = env_delta(name, args);
                events.push(EnvEvent {
                    delta: if is_begin { d } else { d.wrapping_neg() },
                    closed: true,
                    is_begin,
                });
            } else {
                events.push(EnvEvent {
                    delta: if is_begin { 1 } else { -1 },
                    closed: false,
                    is_begin,
                });
            }
        }
        i += 1;
    }
    events
}

fn calculate_indent(text: &str, before: i8, args: &ResolvedArgs) -> Indent {
    let code = code_portion(text);
    // Generic delimiter scan (including braces belonging to commands).
    let mut cum: i8 = before;
    let mut min_cum: i8 = before;
    for c in code.chars() {
        match c {
            '{' | '[' | '(' => cum = cum.wrapping_add(1),
            '}' | ']' | ')' => cum = cum.wrapping_sub(1),
            _ => {}
        }
        if cum < min_cum {
            min_cum = cum;
        }
    }
    let events = env_events(code, args);
    let mut env_net: i8 = 0;
    let mut env_open: i32 = 0;
    let mut env_excess: i32 = 0;
    for ev in &events {
        env_net = env_net.wrapping_add(ev.delta);
        if ev.closed {
            if ev.is_begin {
                if ev.delta > 0 {
                    env_open += i32::from(ev.delta);
                }
            } else {
                let weight = i32::from(ev.delta).abs();
                if weight > 0 {
                    if env_open >= weight {
                        env_open -= weight;
                    } else {
                        env_excess += weight - env_open;
                        env_open = 0;
                    }
                }
            }
        }
    }
    let mut visual = min_cum.wrapping_sub(env_excess as i8);
    if before != 0 && find_item_pattern(code).is_some() {
        visual = visual.wrapping_sub(1);
    }
    let actual = cum.wrapping_add(env_net);
    Indent { actual, visual }
}

fn apply_indent(text: &str, indent: Indent, args: &ResolvedArgs) -> String {
    let content = text.trim();
    if indent.visual > 0 {
        let n_i8 = indent.visual.wrapping_mul(args.tabsize as i8);
        let n = usize::try_from(n_i8).expect("Visual indent is non-negative.");
        let ch = match args.tabchar {
            TabChar::Space => " ",
            TabChar::Tab => "\t",
        };
        let mut s = ch.repeat(n);
        s.push_str(content);
        return s.trim_end().to_string();
    }
    content.to_string()
}

fn contains_verbatim_begin(text: &str, args: &ResolvedArgs) -> bool {
    args.verbatims.iter().any(|env| text.contains(&format!("\\begin{{{}}}", env)))
}
fn contains_verbatim_end(text: &str, args: &ResolvedArgs) -> bool {
    args.verbatims.iter().any(|env| text.contains(&format!("\\end{{{}}}", env)))
}

fn record_indent(
    indents: &mut Vec<(usize, Indent)>,
    cur: usize,
    old: usize,
    indent: Indent,
    text: &str,
    file: &str,
    logger: &Logger,
) {
    logger.trace(file, &format!("Line {} ({}). Indent: actual = {}, visual = {}: {}", cur, old, indent.actual, indent.visual, text));
    if indent.actual < 0 || indent.visual < 0 {
        logger.warn(file, &format!("Line {} ({}). Indent is negative. {}", cur, old, text.trim()));
    }
    indents.push((cur, indent));
}

struct WrapResult {
    first: String,
    rest: String,
}

fn wrap_line(
    text: &str,
    cur: usize,
    old: usize,
    args: &ResolvedArgs,
    file: &str,
    logger: &Logger,
) -> Option<WrapResult> {
    // Find candidate wrap characters.
    let chars: Vec<(usize, char)> = text.char_indices().collect();
    let total_chars = chars.len();
    let mut candidates: Vec<usize> = Vec::new(); // indices into chars
    for (ci, (_bi, c)) in chars.iter().enumerate() {
        if args.wrap_chars.contains(c) {
            let rest_start_ci = ci + 1;
            if ci == 0 || rest_start_ci >= total_chars {
                continue;
            }
            // Remainder must contain non-whitespace.
            let rest_byte = chars[rest_start_ci].0;
            if text[rest_byte..].trim().is_empty() {
                continue;
            }
            candidates.push(ci);
        }
    }
    if candidates.is_empty() {
        logger.warn(file, &format!("Line {} ({}). Line cannot be wrapped. {}", cur, old, text));
        return None;
    }
    let chosen = if let Some(c) = candidates.iter().copied().filter(|ci| *ci < args.wrapmin).max() {
        c
    } else {
        candidates.iter().copied().filter(|ci| *ci >= args.wrapmin).min().unwrap_or(candidates[0])
    };
    let chosen_byte = chars[chosen].0;
    let after_byte = chosen_byte + chars[chosen].1.len_utf8();
    let first = text[..after_byte].to_string();
    let mut rest = text[after_byte..].to_string();
    if first.trim_end().len() > args.wraplen {
        logger.warn(file, &format!("Line {} ({}). Line cannot be wrapped. {}", cur, old, text));
    }
    if let Some(cstart) = comment_start(text) {
        if chosen_byte >= cstart && !rest.trim_start().starts_with('%') {
            rest = format!("% {}", rest);
        }
    }
    Some(WrapResult { first, rest })
}

pub fn format_text(old_text: &str, args: &ResolvedArgs, file: &str, logger: &Logger) -> String {
    logger.info(file, "Formatting started. ");
    let expanded = if args.tabchar == TabChar::Space {
        old_text.replace('\t', &" ".repeat(usize::from(args.tabsize)))
    } else {
        old_text.to_string()
    };
    let mut raw: Vec<String> = expanded.lines().map(ToString::to_string).collect();
    if raw.len() > 2 {
        for i in (2..raw.len()).rev() {
            if raw[i].is_empty() && raw[i - 1].is_empty() {
                raw.remove(i);
            }
        }
    }
    let mut lines: Vec<Line> = raw
        .into_iter()
        .enumerate()
        .map(|(i, s)| Line { text: s.trim_end().to_string(), old: i + 1 })
        .collect();

    let mut out_lines: Vec<String> = Vec::new();
    let mut indents: Vec<(usize, Indent)> = Vec::new();
    let mut actual: i8 = 0;
    let mut verbatim_count: i32 = 0;
    let mut ignoring = false;
    let mut idx = 0usize;

    while idx < lines.len() {
        let cur = idx + 1;
        let line = lines[idx].clone();
        let old = line.old;
        let trimmed = line.text.trim().to_string();

        let mut ignored = false;
        if trimmed.ends_with("% tex-fmt: off") {
            if ignoring {
                logger.warn(file, &format!("Line {} ({}). Cannot begin ignore block: {}", cur, old, trimmed));
            } else {
                ignoring = true;
            }
            ignored = true;
        } else if trimmed.ends_with("% tex-fmt: on") {
            if ignoring {
                ignoring = false;
            } else {
                logger.warn(file, &format!("Line {} ({}). No ignore block to end. {}", cur, old, trimmed));
            }
            ignored = true;
        } else if ignoring {
            ignored = true;
        }
        if trimmed.ends_with("% tex-fmt: skip") {
            ignored = true;
        }

        let vb_before = verbatim_count;
        if contains_verbatim_begin(&line.text, args) {
            verbatim_count += 1;
        } else if contains_verbatim_end(&line.text, args) {
            verbatim_count -= 1;
        }
        if verbatim_count < 0 {
            logger.warn(file, &format!("Line {} ({}). Verbatim count is negative. {}", cur, old, trimmed));
        }
        if vb_before > 0 || verbatim_count > 0 {
            ignored = true;
        }

        if ignored {
            out_lines.push(line.text.trim_end().to_string());
            idx += 1;
            continue;
        }

        let mut work = line.text.trim_start().to_string();

        if let Some(pos) = find_split_point(&work) {
            logger.trace(file, &format!("Line {} ({}). Placing environment on new line. {}", cur, old, work.trim()));
            let rest = work[pos..].to_string();
            let first = work[..pos].to_string();
            lines[idx].text = first.clone();
            lines.insert(idx + 1, Line { text: rest, old });
            work = first;
        }

        let before = actual;
        let mut indent = calculate_indent(&work, before, args);
        record_indent(&mut indents, cur, old, indent, &work, file, logger);
        actual = indent.actual;

        // Wrapping handling. This may split the line; after a split we
        // recalculate the indent of the first segment.
        let mut segment = work;
        loop {
            if args.wrap && segment.chars().count() > args.wraplen {
                logger.trace(file, &format!("Line {} ({}). Wrapping long line. {}", cur, old, segment));
                match wrap_line(&segment, cur, old, args, file, logger) {
                    Some(wr) => {
                        lines.insert(idx + 1, Line { text: wr.rest, old });
                        segment = wr.first;
                        indent = calculate_indent(&segment, before, args);
                        record_indent(&mut indents, cur, old, indent, &segment, file, logger);
                        actual = indent.actual;
                        // Continue the loop to check the first segment again.
                        continue;
                    }
                    None => {
                        out_lines.push(apply_indent(&segment, indent, args));
                        break;
                    }
                }
            } else {
                out_lines.push(apply_indent(&segment, indent, args));
                break;
            }
        }
        idx += 1;
    }

    if let Some(last) = indents.last().copied() {
        if last.1.actual != 0 {
            let last_non = indents
                .iter()
                .rposition(|(_, ind)| ind.visual == 0)
                .map(|i| indents[i].0)
                .unwrap_or(1);
            logger.warn(file, &format!("Indent does not return to zero. Last non-indented line is line {} ", last_non));
        }
        if let Some(first) = indents.iter().find(|(_, ind)| ind.actual < 0 || ind.visual < 0) {
            logger.warn(file, &format!("Negative indents. First negatively indented line is line {} ", first.0));
        }
    }

    logger.info(file, "Formatting complete. ");
    let joined = out_lines.join("\n");
    format!("{}\n", joined.trim_end())
}

// Keep Level import used in some configurations (the logger methods wrap it).
#[allow(dead_code)]
fn _unused(_: Level) {}
