) -> Option<WrapResult> {
    // Find candidate wrap characters.
    let chars: Vec<(usize, char)> = text.char_indices().collect();
    let total_chars = chars.len();
    let mut candidates: Vec<usize> = Vec::new(); // indices into chars
    for (ci, (_bi, c)) in chars.iter().enumerate() {
        if args.wrap_chars.contains(c) {
            let rest_start_ci = ci + 1;
            if ci == 0 || rest_start_ci >= total_chars {
                continue;
            }
            // Remainder must contain non-whitespace.
            let rest_byte = chars[rest_start_ci].0;
            if text[rest_byte..].trim().is_empty() {
                continue;
            }
            candidates.push(ci);
        }
    }
    if candidates.is_empty() {
        logger.warn(file, &format!("Line {} ({}). Line cannot be wrapped. {}", cur, old, text));
        return None;
    }
    let chosen = if let Some(c) = candidates.iter().copied().filter(|ci| *ci < args.wrapmin).max() {
        c
    } else {
        candidates.iter().copied().filter(|ci| *ci >= args.wrapmin).min().unwrap_or(candidates[0])
    };
    let chosen_byte = chars[chosen].0;
    let after_byte = chosen_byte + chars[chosen].1.len_utf8();
    let first = text[..after_byte].to_string();
    let mut rest = text[after_byte..].to_string();
    if first.trim_end().len() > args.wraplen {
        logger.warn(file, &format!("Line {} ({}). Line cannot be wrapped. {}", cur, old, text));
    }
    if let Some(cstart) = comment_start(text) {
        if chosen_byte >= cstart && !rest.trim_start().starts_with('%') {
            rest = format!("% {}", rest);
        }
    }
    Some(WrapResult { first, rest })
}

pub fn format_text(old_text: &str, args: &ResolvedArgs, file: &str, logger: &Logger) -> String {
    logger.info(file, "Formatting started. ");
    let expanded = if args.tabchar == TabChar::Space {
        old_text.replace('\t', &" ".repeat(usize::from(args.tabsize)))
    } else {
        old_text.to_string()
    };
    let mut raw: Vec<String> = expanded.lines().map(ToString::to_string).collect();
    if raw.len() > 2 {
        for i in (2..raw.len()).rev() {
            if raw[i].is_empty() && raw[i - 1].is_empty() {
                raw.remove(i);
            }
        }
    }
    let mut lines: Vec<Line> = raw
        .into_iter()
        .enumerate()
        .map(|(i, s)| Line { text: s.trim_end().to_string(), old: i + 1 })
        .collect();

    let mut out_lines: Vec<String> = Vec::new();
    let mut indents: Vec<(usize, Indent)> = Vec::new();
    let mut actual: i8 = 0;
    let mut verbatim_count: i32 = 0;
    let mut ignoring = false;
    let mut idx = 0usize;

    while idx < lines.len() {
        let cur = idx + 1;
        let line = lines[idx].clone();
        let old = line.old;
        let trimmed = line.text.trim().to_string();

        let mut ignored = false;
        if trimmed.ends_with("% tex-fmt: off") {
            if ignoring {
                logger.warn(file, &format!("Line {} ({}). Cannot begin ignore block: {}", cur, old, trimmed));
            } else {
                ignoring = true;
            }
            ignored = true;
        } else if trimmed.ends_with("% tex-fmt: on") {
            if ignoring {
                ignoring = false;
            } else {
                logger.warn(file, &format!("Line {} ({}). No ignore block to end. {}", cur, old, trimmed));
            }
            ignored = true;
        } else if ignoring {
            ignored = true;
        }
        if trimmed.ends_with("% tex-fmt: skip") {
            ignored = true;
        }

        let vb_before = verbatim_count;
        if contains_verbatim_begin(&line.text, args) {
            verbatim_count += 1;
        } else if contains_verbatim_end(&line.text, args) {
            verbatim_count -= 1;
        }
        if verbatim_count < 0 {
            logger.warn(file, &format!("Line {} ({}). Verbatim count is negative. {}", cur, old, trimmed));
        }
        if vb_before > 0 || verbatim_count > 0 {
            ignored = true;
        }

        if ignored {
            out_lines.push(line.text.trim_end().to_string());
            idx += 1;
            continue;
        }

        let mut work = line.text.trim_start().to_string();

        if let Some(pos) = find_split_point(&work) {
            logger.trace(file, &format!("Line {} ({}). Placing environment on new line. {}", cur, old, work.trim()));
            let rest = work[pos..].to_string();
            let first = work[..pos].to_string();
            lines[idx].text = first.clone();
            lines.insert(idx + 1, Line { text: rest, old });
            work = first;
        }

        let before = actual;
        let mut indent = calculate_indent(&work, before, args);
        record_indent(&mut indents, cur, old, indent, &work, file, logger);
        actual = indent.actual;

        // Wrapping handling. This may split the line; after a split we
        // recalculate the indent of the first segment.
        let mut segment = work;
        loop {
            if args.wrap && segment.chars().count() > args.wraplen {
                logger.trace(file, &format!("Line {} ({}). Wrapping long line. {}", cur, old, segment));
                match wrap_line(&segment, cur, old, args, file, logger) {
                    Some(wr) => {
                        lines.insert(idx + 1, Line { text: wr.rest, old });
                        segment = wr.first;
                        indent = calculate_indent(&segment, before, args);
                        record_indent(&mut indents, cur, old, indent, &segment, file, logger);
                        actual = indent.actual;
                        // Continue the loop to check the first segment again.
                        continue;
                    }
                    None => {
                        out_lines.push(apply_indent(&segment, indent, args));
                        break;
                    }
                }
            } else {
                out_lines.push(apply_indent(&segment, indent, args));
                break;
            }
        }
        idx += 1;
    }

    if let Some(last) = indents.last().copied() {
        if last.1.actual != 0 {
            let last_non = indents
                .iter()
                .rposition(|(_, ind)| ind.visual == 0)
                .map(|i| indents[i].0)
                .unwrap_or(1);
            logger.warn(file, &format!("Indent does not return to zero. Last non-indented line is line {} ", last_non));
        }
        if let Some(first) = indents.iter().find(|(_, ind)| ind.actual < 0 || ind.visual < 0) {
            logger.warn(file, &format!("Negative indents. First negatively indented line is line {} ", first.0));
        }
    }

    logger.info(file, "Formatting complete. ");
    let joined = out_lines.join("\n");
    format!("{}\n", joined.trim_end())
}

// Keep Level import used in some configurations (the logger methods wrap it).
#[allow(dead_code)]
fn _unused(_: Level) {}
RS
"}

