fn find_config_path() -> Option<PathBuf> {
    let cwd = std::env::current_dir().ok()?;
    let local = cwd.join("tex-fmt.toml");
    if local.exists() {
        return Some(local);
    }
    for anc in cwd.ancestors() {
        if anc.join(".git").is_dir() {
            let cand = anc.join("tex-fmt.toml");
            if cand.exists() {
                return Some(cand);
            }
            break;
        }
    }
    if let Some(dir) = dirs::config_dir() {
        let cand = dir.join("tex-fmt").join("tex-fmt.toml");
        if cand.exists() {
            return Some(cand);
        }
    }
    None
