            cfg.no_indent_envs = arr.iter().filter_map(|x| x.as_str().map(ToString::to_string)).collect();
        }
    }
    if let Some(v) = table.get("tabchar") {
        cfg.tabchar = Some(if v.as_str().unwrap() == "tab" { TabChar::Tab } else { TabChar::Space });
    }
    if let Some(v) = table.get("wrap-chars") {
        if let Some(arr) = v.as_array() {
            cfg.wrap_chars = arr.iter().filter_map(|x| x.as_str()).map(char_from_string).collect();
        }
    }
    if let Some(v) = table.get("check") {
        cfg.check = Some(v.as_bool().unwrap());
    }
    if let Some(v) = table.get("print") {
        cfg.print = Some(v.as_bool().unwrap());
    }
    if let Some(v) = table.get("fail-on-change") {
        cfg.fail_on_change = Some(v.as_bool().unwrap());
    }
    if let Some(v) = table.get("wrap") {
        cfg.wrap = Some(v.as_bool().unwrap());
    }
    if let Some(v) = table.get("wraplen") {
        cfg.wraplen = Some(usize::try_from(v.as_integer().unwrap()).unwrap());
    }
    if let Some(v) = table.get("wrapmin") {
        cfg.wrapmin = Some(usize::try_from(v.as_integer().unwrap()).unwrap());
    }
    if let Some(v) = table.get("tabsize") {
        cfg.tabsize = Some(u8::try_from(v.as_integer().unwrap()).unwrap());
    }
    if let Some(v) = table.get("stdin") {
        cfg.stdin = Some(v.as_bool().unwrap());
    }
    cfg
}

fn combined(mut config_items: Vec<String>, defaults: &[&str]) -> Vec<String> {
    config_items.extend(defaults.iter().map(|s| s.to_string()));
    config_items.dedup();
    config_items
}

pub struct CliValues {
    pub check: bool,
    pub print: bool,
    pub fail_on_change: bool,
    pub nowrap: bool,
    pub wraplen: usize,
    pub wraplen_from_cli: bool,
    pub tabsize: u8,
    pub tabsize_from_cli: bool,
    pub usetabs: bool,
    pub stdin: bool,
    pub config: Option<PathBuf>,
    pub noconfig: bool,
    pub verbose: bool,
    pub quiet: bool,
    pub trace: bool,
}

pub fn resolve(cli: &CliValues) -> ResolvedArgs {
    let (config_display, file_cfg) = if cli.noconfig {
        (cli.config.as_ref().map(|p| p.display().to_string()), FileConfig::default())
    } else if let Some(path) = &cli.config {
        let table = read_config_table(path);
        (Some(path.display().to_string()), extract(&table))
    } else if let Some(path) = find_config_path() {
        let table = read_config_table(&path);
        (Some(path.display().to_string()), extract(&table))
    } else {
        (None, FileConfig::default())
    };

    let mut args = ResolvedArgs {
        check: false,
        print: false,
        fail_on_change: false,
        wrap: true,
        wraplen: 80,
        wrapmin: 70,
        tabsize: 2,
        tabchar: TabChar::Space,
        stdin: false,
        config: config_display,
        verbosity: Verbosity::Warn,
        lists: Vec::new(),
        verbatims: Vec::new(),
        no_indent_envs: Vec::new(),
        wrap_chars: Vec::new(),
    };

    if let Some(v) = file_cfg.verbosity { args.verbosity = v; }
    if let Some(v) = file_cfg.check { args.check = v; }
    if let Some(v) = file_cfg.print { args.print = v; }
    if let Some(v) = file_cfg.fail_on_change { args.fail_on_change = v; }
    if let Some(v) = file_cfg.wrap { args.wrap = v; }
    if let Some(v) = file_cfg.wraplen { args.wraplen = v; }
    if let Some(v) = file_cfg.tabsize { args.tabsize = v; }
    if let Some(v) = file_cfg.tabchar { args.tabchar = v; }
    if let Some(v) = file_cfg.stdin { args.stdin = v; }

    args.lists = combined(file_cfg.lists.clone(), &["itemize", "enumerate", "description", "inlineroman", "inventory"]);
    args.verbatims = combined(file_cfg.verbatims.clone(), &["verbatim", "Verbatim", "lstlisting", "minted", "comment"]);
    args.no_indent_envs = combined(file_cfg.no_indent_envs.clone(), &["document"]);
    let mut wc = file_cfg.wrap_chars.clone();
    wc.push(' ');
    wc.dedup();
    args.wrap_chars = wc;

    if cli.check { args.check = true; }
    if cli.print { args.print = true; }
    if cli.fail_on_change { args.fail_on_change = true; }
    if cli.nowrap { args.wrap = false; }
    if cli.wraplen_from_cli { args.wraplen = cli.wraplen; }
    if cli.tabsize_from_cli { args.tabsize = cli.tabsize; }
    if cli.usetabs { args.tabchar = TabChar::Tab; }
    if cli.stdin { args.stdin = true; }
    if cli.trace {
        args.verbosity = Verbosity::Trace;
    } else if cli.verbose {
        args.verbosity = Verbosity::Info;
    } else if cli.quiet {
        args.verbosity = Verbosity::Error;
    }

    if let Some(wm) = file_cfg.wrapmin {
        args.wrapmin = std::cmp::min(wm, args.wraplen);
    } else if args.wraplen >= 50 {
        args.wrapmin = args.wraplen - 10;
    } else {
        args.wrapmin = args.wraplen;
    }

    args
}

pub fn print_args(args: &ResolvedArgs) {
    println!("tex-fmt");
    println!("  check:                   {}", args.check);
    println!("  print:                   {}", args.print);
    println!("  fail-on-change:          {}", args.print_mode());
    println!("  wrap:                    {}", args.wrap);
    println!("  wraplen:                 {}", args.wraplen);
    println!("  wrapmin:                 {}", args.wrapmin);
    println!("  tabsize:                 {}", args.tabsize);
    println!("  tabchar:                 {}", args.tabchar.name());
    println!("  stdin:                   {}", args.stdin);
    match &args.config {
        Some(c) => println!("  config:                  {}", c),
        None => println!("  config:                  None"),
    }
    println!("  verbosity:               {}", args.verbosity.name());
    print_list("lists:", &args.lists);
    print_list("verbatims:", &args.verbatims);
    print_list("no-indent-envs:", &args.no_indent_envs);
    // wrap-chars are chars; display each on its own continuation line.
    if args.wrap_chars.is_empty() {
        println!("  wrap-chars:               ");
    } else {
        for (i, c) in args.wrap_chars.iter().enumerate() {
            if i == 0 {
                println!("  wrap-chars:              {}", c);
            } else {
                println!("                           {}", c);
            }
        }
    }
}

fn print_list(name: &str, items: &[String]) {
    if items.is_empty() {
        println!("  {:25}", name);
        return;
    }
    for (i, item) in items.iter().enumerate() {
        if i == 0 {
            // 2 spaces + name padded so values start at column 27.
            print!("  ");
            print!("{:<25}", name);
            println!("{}", item);
        } else {
            println!("                           {}", item);
        }
    }
}
RS
"}

