{"command":"cat > src/main.rs <<'RS'
mod config;
mod format;
mod logging;
mod write;

use clap::{value_parser, Arg, ArgAction, Command};
use config::{CliValues, ResolvedArgs};
use logging::{Logger, Verbosity};
use std::io::{self, Write};
use std::path::{Path, PathBuf};

fn cli() -> Command {
    Command::new("tex-fmt")
        .version("0.5.6")
        .about("LaTeX formatter written in Rust")
        .help_template("{name} {version}\n\n{about}\n\n{usage-heading} {usage}\n\n{all-args}")
        .arg(
            Arg::new("files")
                .help("List of files to be formatted")
                .num_args(0..)
                .value_name("files"),
        )
        .arg(Arg::new("check").short('c').long("check").help("Check formatting, do not modify files").action(ArgAction::SetTrue))
        .arg(Arg::new("print").short('p').long("print").help("Print to stdout, do not modify files").action(ArgAction::SetTrue))
        .arg(Arg::new("fail-on-change").short('f').long("fail-on-change").help("Format files and return non-zero exit code if files are modified").action(ArgAction::SetTrue))
        .arg(Arg::new("nowrap").short('n').long("nowrap").help("Do not wrap long lines").action(ArgAction::SetTrue))
        .arg(Arg::new("wraplen").short('l').long("wraplen").value_name("N").help("Line length for wrapping").default_value("80").value_parser(value_parser!(usize)))
        .arg(Arg::new("tabsize").short('t').long("tabsize").value_name("N").help("Number of characters to use as tab size").default_value("2").value_parser(value_parser!(u8)))
        .arg(Arg::new("usetabs").long("usetabs").help("Use tabs instead of spaces for indentation").action(ArgAction::SetTrue))
        .arg(Arg::new("stdin").short('s').long("stdin").help("Process stdin as a single file, output to stdout").action(ArgAction::SetTrue))
        .arg(Arg::new("config").long("config").value_name("PATH").help("Path to config file").value_parser(value_parser!(PathBuf)))
        .arg(Arg::new("noconfig").long("noconfig").help("Do not read any config file").action(ArgAction::SetTrue))
        .arg(Arg::new("verbose").short('v').long("verbose").help("Show info messages").action(ArgAction::SetTrue))
        .arg(Arg::new("quiet").short('q').long("quiet").help("Hide warning messages").action(ArgAction::SetTrue))
        .arg(Arg::new("trace").long("trace").help("Show trace messages").action(ArgAction::SetTrue))
        .arg(Arg::new("completion").long("completion").value_name("SHELL").help("Generate shell completion script").value_parser(value_parser!(clap_complete::Shell)))
        .arg(Arg::new("man").long("man").help("Generate man page").action(ArgAction::SetTrue))
        .arg(Arg::new("args").long("args").help("Print arguments passed to tex-fmt and exit").action(ArgAction::SetTrue))
        .arg(Arg::new("recursive").short('r').long("recursive").help("Recursively search for files to format").action(ArgAction::SetTrue))
}

struct Gathered {
    files: Vec<PathBuf>,
    directory_error: bool,
}

fn gather_files(cli_files: &[String], recursive: bool) -> Gathered {
    if !recursive {
        let mut directory_error = false;
        let mut files = Vec::new();
        for f in cli_files {
            let path = PathBuf::from(f);
            if path.is_dir() {
                directory_error = true;
            }
            let transformed = if path.extension().is_none() {
                path.with_extension("tex")
            } else {
                path
            };
            files.push(transformed);
        }
        files.dedup();
        return Gathered { files, directory_error };
    }

    let root_strings: Vec<String> = if cli_files.is_empty() {
        vec![".".to_string()]
    } else {
        cli_files.to_vec()
    };
    let mut roots: Vec<PathBuf> = Vec::new();
    for f in &root_strings {
        let path = PathBuf::from(f);
        if path.is_dir() {
            roots.push(path);
        } else if path.extension().is_none() {
            roots.push(path.with_extension("tex"));
        } else {
            roots.push(path);
        }
    }
    if roots.is_empty() {
        return Gathered { files: Vec::new(), directory_error: false };
    }
    let mut builder = ignore::WalkBuilder::new(&roots[0]);
    for root in &roots[1..] {
        builder.add(root);
    }
    let mut files = Vec::new();
    for entry in builder.build() {
        let Ok(entry) = entry else { continue };
        let path = entry.path().to_path_buf();
        let depth = entry.depth();
        let is_regular = entry.file_type().map(|t| t.is_file()).unwrap_or(false);
        if depth == 0 {
            if path.is_file() {
                files.push(path);
            }
            continue;
        }
        if !is_regular {
            continue;
        }
        if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
            if ["tex", "bib", "cls", "sty"].contains(&ext) {
                files.push(path);
            }
        }
    }
    files.dedup();
    Gathered { files, directory_error: false }
}

fn valid_extension(path: &Path) -> bool {
    matches!(
        path.extension().and_then(|e| e.to_str()),
        Some("tex") | Some("bib") | Some("cls") | Some("sty")
    )
}

fn run() -> i32 {
    let matches = cli().get_matches();

    if let Some(shell) = matches.get_one::<clap_complete::Shell>("completion").cloned() {
        let text = match shell {
            clap_complete::Shell::Bash => include_str!("../assets/completion.bash"),
            clap_complete::Shell::Elvish => include_str!("../assets/completion.elvish"),
            clap_complete::Shell::Fish => include_str!("../assets/completion.fish"),
            clap_complete::Shell::PowerShell => include_str!("../assets/completion.powershell"),
            clap_complete::Shell::Zsh => include_str!("../assets/completion.zsh"),
            _ => "",
        };
        print!("{}", text);
        return 0;
    }
    if matches.get_flag("man") {
        print!("{}", include_str!("../assets/man.txt"));
        return 0;
    }

    let files: Vec<String> = matches
        .get_many::<String>("files")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    let cli_values = CliValues {
        check: matches.get_flag("check"),
        print: matches.get_flag("print"),
        fail_on_change: matches.get_flag("fail-on-change"),
        nowrap: matches.get_flag("nowrap"),
        wraplen: *matches.get_one::<usize>("wraplen").unwrap_or(&80),
        wraplen_from_cli: matches.value_source("wraplen") == Some(clap::parser::ValueSource::CommandLine),
        tabsize: *matches.get_one::<u8>("tabsize").unwrap_or(&2),
        tabsize_from_cli: matches.value_source("tabsize") == Some(clap::parser::ValueSource::CommandLine),
        usetabs: matches.get_flag("usetabs"),
        stdin: matches.get_flag("stdin"),
        config: matches.get_one::<PathBuf>("config").cloned(),
        noconfig: matches.get_flag("noconfig"),
        verbose: matches.get_flag("verbose"),
        quiet: matches.get_flag("quiet"),
        trace: matches.get_flag("trace"),
    };

    let args: ResolvedArgs = config::resolve(&cli_values);

    if matches.get_flag("args") {
        config::print_args(&args);
        return 0;
    }

    let logger = Logger::new(args.verbosity);
    let recursive = matches.get_flag("recursive");
    let gathered = gather_files(&files, recursive);

    if args.stdin {
        let mut code = 0;
        if gathered.directory_error {
            logger.error("", "A directory was passed without --recursive. ");
            code = 1;
        }
        if !gathered.files.is_empty() {
            logger.error("", "Do not provide file name(s) when using --stdin. ");
            code = 1;
        }
        if code != 0 {
            logger.flush();
            return code;
        }
        match io::read_to_string(io::stdin()) {
            Err(e) => {
                logger.error("<stdin>", &format!("Could not read from stdin: {} ", e));
                logger.flush();
                return 1;
            }
            Ok(input) => {
                logger.trace("<stdin>", &format!("Read {} bytes. ", input.len()));
                let formatted = format::format_text(&input, &args, "<stdin>", &logger);
                print!("{}", formatted);
                let _ = io::stdout().flush();
                logger.flush();
                return 0;
            }
        }
    }

    if gathered.directory_error {
        logger.error("", "A directory was passed without --recursive. ");
        logger.flush();
        return 1;
    }
    if gathered.files.is_empty() {
        logger.error("", "No files specified. Provide filenames, or pass --recursive or --stdin. ");
        logger.flush();
        return 1;
    }

    let mut code = 0;
    for path in &gathered.files {
        let target = path.display().to_string();
        match std::fs::read_to_string(path) {
            Err(_) => {
                if valid_extension(path) {
                    logger.error(&target, "Could not open file. ");
                } else {
                    logger.error(&target, "File type invalid. ");
                }
                code = 1;
            }
            Ok(old) => {
