pub fn verbatim_ranges(text: &str) -> Vec<(usize, usize)> {


















    let mut ranges = Vec::new();
    let mut i = 0usize;
    while i < text.len() {
        if !text.is_char_boundary(i) {
            i += 1;
            continue;
        }
        let rest = &text[i..];
        if rest.starts_with("\\verb|") || rest.starts_with("\\verb+") {
