            let first = find_any(text, i + 11);
            let first_len = text[first..].chars().next().unwrap().len_utf8();
            let end = find_any(text, first + first_len);
            ranges.push((i, end));
            i = end + text[end..].chars().next().unwrap().len_utf8();
        } else {
            i += rest.chars().next().map(|c| c.len_utf8()).unwrap_or(1);
        }
    }
    ranges
}

fn find_delimiter(text: &str, from: usize, delim: char) -> usize {
    text[from..].char_indices().find(|(_, c)| *c == delim).map(|(i, _)| from + i).unwrap()
