import pathlib
p=pathlib.Path("src/format.rs"); s=p.read_text()
# Replace EnvEvent struct and env_events fn with singular functions
start=s.index("#[derive(Clone, Copy)]\nstruct EnvEvent")
end=s.index("fn calculate_indent", start)
new='''fn env_actual_delta(code: &str, args: &ResolvedArgs) -> i8 {
    if suppress_command_patterns(code) {
        return 0;
    }
    let has = |prefix: &str, env: &String| code.contains(&format!("\\\\{}{{{}}}", prefix, env));
    if args.no_indent_envs.iter().any(|e| has("begin", e)) {
        0
    } else if args.lists.iter().any(|e| has("begin", e)) {
        2
    } else if code.contains("\\\\begin{") {
        1
    } else if args.no_indent_envs.iter().any(|e| has("end", e)) {
        0
    } else if args.lists.iter().any(|e| has("end", e)) {
        -2
    } else if code.contains("\\\\end{") {
        -1
    } else {
        0
    }
}

fn env_visual_excess(code: &str, args: &ResolvedArgs) -> i32 {
    if suppress_command_patterns(code) {
        return 0;
    }
    let has_end = |env: &String| code.contains(&format!("\\\\end{{{}}}", env));
    if args.no_indent_envs.iter().any(|e| has_end(e)) {
        0
    } else if args.lists.iter().any(|e| has_end(e)) {
        2
    } else if code.contains("\\\\end{") {
        1
    } else {
        0
    }
}

'''
s=s[:start]+new+s[end:]
# Replace events usage in calculate_indent
old='''    let events = env_events(code, args);
    let mut env_net: i8 = 0;
    let mut env_open: i32 = 0;
    let mut env_excess: i32 = 0;
    for ev in &events {
        env_net = env_net.wrapping_add(ev.delta);
        if ev.closed {
            if ev.is_begin {
                if ev.delta > 0 {
                    env_open += i32::from(ev.delta);
                }
            } else {
                let weight = i32::from(ev.delta).abs();
                if weight > 0 {
                    if env_open >= weight {
                        env_open -= weight;
                    } else {
                        env_excess += weight - env_open;
                        env_open = 0;
                    }
                }
            }
        }
    }
    let effective_env_excess = if before != 0 { env_excess } else { 0 };'''
new2='''    let env_net = env_actual_delta(code, args);
    let env_excess = env_visual_excess(code, args);
    let effective_env_excess = if before != 0 { env_excess } else { 0 };'''
assert old in s
s=s.replace(old,new2)
# env_delta function may now be unused; keep (dead)
p.write_text(s)
PY
cargo build --release --offline 2>&1 | tail -20"}

