) -> Option<WrapResult> {
    let indent_len = indent_amount(indent, args);
    // Find candidate wrap characters.
    let chars: Vec<(usize, char)> = text.char_indices().collect();
    let total_chars = chars.len();
    let comment_first_content = if text.trim_start().starts_with('%') {
        text.char_indices()
            .enumerate()
            .find(|(_, (_, c))| *c != '%' && !c.is_whitespace())
            .map(|(ci, _)| ci)
    } else {
        None
    };
    let mut raw_candidates: Vec<usize> = Vec::new();
    for (ci, (_bi, c)) in chars.iter().enumerate() {
        if let Some(fc) = comment_first_content {
