    // only if a candidate occurs after it begins.
    let mut candidates = raw_candidates.clone();
    if let Some(vstart) = crate::wrap::first_verbatim_start(text) {
        let needs_check = raw_candidates.iter().any(|ci| chars[*ci].0 > vstart);
