pub fn first_verbatim_start(text: &str) -> Option<usize> {
    let pats = ["\\verb|", "\\verb+", "\\mintinline"];
    let mut best: Option<usize> = None;
    for pat in pats {
        if let Some(pos) = text.find(pat) {
            best = Some(match best {
                None => pos,
                Some(b) => b.min(pos),
            });
        }
    }
    best
}

pub fn verbatim_ranges(text: &str) -> Vec<(usize, usize)> {
    let mut ranges = Vec::new();
    let mut i = 0usize;
    while i < text.len() {
        if !text.is_char_boundary(i) {
            i += 1;
            continue;
        }
        let rest = &text[i..];
        if rest.starts_with("\\verb|") || rest.starts_with("\\verb+") {
            let delim = rest.chars().nth(5).unwrap();
            let end = find_after(text, i + 6, |c| c == delim);
            ranges.push((i, end));
            break;
        } else if rest.starts_with("\\mintinline") {
            let first = find_after(text, i + 11, |c| c == '|' || c == '+');
            let first_len = text[first..].chars().next().unwrap().len_utf8();
            let end = find_after(text, first + first_len, |c| c == '|' || c == '+');
            ranges.push((i, end));
            break;
        } else {
            i += rest.chars().next().map(|c| c.len_utf8()).unwrap_or(1);
        }
    }
    ranges
}

fn find_after(text: &str, from: usize, accept: impl Fn(char) -> bool) -> usize {
    let verbatim_end = text[from..].find(|c: char| accept(c)).unwrap();
    verbatim_end + from
}
